/*******************************************************************************
 * Size: 48 px
 * Bpp: 4
 * P7.51: subset of LVGL's built-in lv_font_montserrat_48 (which this replaces;
 * LV_FONT_MONTSERRAT_48 is 0). Glyphs: space % - 0-9 : plus LV_SYMBOL_AUDIO,
 * OK, TINT, ENVELOPE, CHARGE, BELL, KEYBOARD, EDIT -- exactly what the three
 * users can render (ui_audio_notes.cpp rec_time_lbl, hal/charge_task.cpp,
 * menu_app.cpp pick_icon_font's home tiles). Add a glyph here before using
 * this font for new text.
 * Generated from the repo root twice, because LVGL's stock font changed
 * generator: lv_font_conv 1.5.2 is bit-exact with LVGL <= 9.5, and 1.5.3
 * (11 of 22 glyphs differ by a few edge pixels at 1/15 alpha) with LVGL 9.6.
 * glyph_bitmap is version-gated; everything else is the same in both:
 *   npx lv_font_conv@1.5.2 <Opts below>   (and again with @1.5.3)
 * Post-generation edits (to match the stock descriptor exactly): line_height
 * 52 / base_line 9 (the subset alone measures 50/7), and the PUBLIC FONT and
 * font_dsc blocks replaced with the stock file's version-guarded ones
 * (no .cache on v9, cap_height/x_height on 9.6, static_bitmap on >= 9.3).
 * Opts: --no-compress --no-prefilter --bpp 4 --size 48 --font .pio/libdeps/tlora_pager/lvgl/scripts/built_in_font/Montserrat-Medium.ttf -r 0x20,0x25,0x2D,0x30-0x3A --font .pio/libdeps/tlora_pager/lvgl/scripts/built_in_font/FontAwesome5-Solid+Brands+Regular.woff -r 61441,61452,61507,61664,61671,61683,61724,62212 --format lvgl --lv-include lvgl.h --force-fast-kern-format -o src/fonts/font_montserrat_48_subset.c
 ******************************************************************************/

